// Persian UI text: English phrase -> Persian, used by app.js (faText) when the
// panel language is FA. Loaded on demand, only in Persian mode.
//
// Glossary (keep consistent): tunnel تونل · server سرور · Iran server سرور ایران ·
// foreign server سرور خارج · peer همتا · setup راه‌اندازی · bundle باندل ·
// carrier حامل · failover جابه‌جایی خودکار · rescue نجات · watchdog نگهبان ·
// diagnostics عیب‌یابی · restart ری‌استارت · license لایسنس.
// Technical names stay Latin: GRE, FRP, frps, frpc, Backhaul, WSS, KCP, QUIC, TCP,
// UDP, MTU, MSS, BBR, IP, DNAT, SNI, TLS, HTTPS, Bagher's SSH, iPerf3, VLESS.
