"Every failed panel action is recorded here with its code — newest last.": "هر کار ناموفق پنل با کدش اینجا ثبت می‌شود؛ جدیدترین در آخر.",
"Filter errors…": "فیلتر خطاها…",
"Filter errors": "فیلتر خطاها",
"Apply": "اعمال",
"Restart": "ری‌استارت",
"Speed-first controls for wire-speed streaming. Keep proxy encryption and compression OFF for already-encrypted streams (VLESS, Reality, Trojan) to eliminate latency and CPU bottlenecks.": "تنظیمات سرعت‌محور برای انتقال با حداکثر سرعت خط. برای جریان‌هایی که از قبل رمز شده‌اند (VLESS، Reality، Trojan) رمزنگاری و فشرده‌سازی پراکسی را خاموش نگه دارید تا تأخیر و فشار CPU حذف شود.",
"FRP Crypto": "رمزنگاری FRP",
"Enc: Off · Comp: Off": "رمز: خاموش · فشرده: خاموش",
"Work-conn pool (frpc / frps)": "استخر اتصال کاری (frpc / frps)",
"Auto Pool decision": "تصمیم استخر خودکار",
"FRP Tunnel Crypto": "رمزنگاری تونل FRP",
"Configures layer-2 crypto and snappy compression on FRP reverse tunnels. Speed-first defaults keep encryption and compression OFF so already-encrypted protocols (VLESS, Trojan) run at wire speed.": "رمزنگاری لایه‌ی دوم و فشرده‌سازی Snappy را روی تونل‌های معکوس FRP تنظیم می‌کند. پیش‌فرض سرعت‌محور رمزنگاری و فشرده‌سازی را خاموش نگه می‌دارد تا پروتکل‌های رمزشده (VLESS، Trojan) با سرعت کامل کار کنند.",
"Proxy Encryption (transport.useEncryption)": "رمزنگاری پراکسی (transport.useEncryption)",
"Encrypts data between frpc and frps with AES-128. Keep disabled for already-encrypted streams (e.g. VLESS) to eliminate double-crypto overhead on low-power VPS.": "داده‌ی بین frpc و frps را با AES-128 رمز می‌کند. برای جریان‌های رمزشده (مثل VLESS) خاموش بماند تا سربار رمزنگاری دوباره روی VPS ضعیف حذف شود.",
"Proxy Compression (transport.useCompression)": "فشرده‌سازی پراکسی (transport.useCompression)",
"Snappy compression per proxy. Keep disabled when streaming incompressible encrypted data (VLESS, TLS) to avoid wasting CPU cycles.": "فشرده‌سازی Snappy برای هر پراکسی. برای داده‌ی رمزشده‌ی غیرقابل‌فشرده‌سازی (VLESS، TLS) خاموش بماند تا CPU هدر نرود.",
"TCP Multiplexing (transport.tcpMux)": "مالتی‌پلکس TCP (transport.tcpMux)",
"Packs every user stream into ONE TCP connection between frpc and frps. Measured over GRE it roughly halves tunnel throughput (e.g. 460 vs 1010 Mbit on Finland). Default is OFF (max speed). It must be identical on the Iran hub AND every foreign server, otherwise frpc cannot log in.": "همه‌ی جریان‌های کاربران را در یک اتصال TCP بین frpc و frps می‌گذارد. روی GRE توان عبوری تونل را تقریباً نصف می‌کند (مثلاً ۴۶۰ در برابر ۱۰۱۰ مگابیت روی فنلاند). پیش‌فرض خاموش است (حداکثر سرعت). باید روی هاب ایران و همه‌ی سرورهای خارج یکسان باشد، وگرنه frpc نمی‌تواند وارد شود.",
"Live: —": "زنده: —",
"Restart Tunnels": "ری‌استارت تونل‌ها",
"Save Settings": "ذخیره‌ی تنظیمات",
"Reset all performance settings to clean wire-speed defaults": "بازگرداندن همه‌ی تنظیمات کارایی به پیش‌فرض‌های سرعت کامل",
"Reset to Safe Defaults": "بازگشت به پیش‌فرض‌های امن",
"Auto Pool (FRP work connections)": "استخر خودکار (اتصال‌های کاری FRP)",
"Sizes frpc poolCount and frps maxPoolCount from pool-full errors, active connections, CPU and free RAM. Scales up fast, scales down slowly, restarts only frpc and only when few users are connected.": "مقدار poolCount در frpc و maxPoolCount در frps را از روی خطای پرشدن استخر، اتصال‌های فعال، CPU و RAM آزاد تنظیم می‌کند. سریع بزرگ و آهسته کوچک می‌کند و فقط frpc را، آن هم وقتی کاربران کمی وصل‌اند، ری‌استارت می‌کند.",
"Auto": "خودکار",
"Auto Pool (recommended)": "استخر خودکار (پیشنهادی)",
"When off, the manual values below are written to frpc.toml / frps.toml as typed.": "وقتی خاموش است، مقدارهای دستی زیر همان‌طور که وارد شده‌اند در frpc.toml / frps.toml نوشته می‌شوند.",
"Last decision": "آخرین تصمیم",
