"maxPoolCount was raised in frps.toml; restart frps during a quiet period to apply it.": "مقدار maxPoolCount در frps.toml بیشتر شد؛ برای اعمال، frps را در زمان کم‌ترافیک ری‌استارت کنید.",
"Client Pool Count (frpc)": "تعداد استخر کلاینت (frpc)",
