"Tunnel {0} ({1}) fails: {2}": "تونل {0} ({1}) کار نمی‌کند: {2}",
"Bagher is enabled but its service is not running": "باقر فعال است ولی سرویسش اجرا نمی‌شود",
"Open the Bagher tab and press Start. Its log shows why it stopped": "تب باقر را باز کنید و «شروع» را بزنید. لاگ آن نشان می‌دهد چرا متوقف شده",
"Check that the foreign server is online and that its SSH port accepts this server's key": "بررسی کنید سرور خارج روشن باشد و پورت SSH آن کلید این سرور را بپذیرد",
"Check that the foreign server is online and that its SSH port accepts this server's key. Last error: {0}": "بررسی کنید سرور خارج روشن باشد و پورت SSH آن کلید این سرور را بپذیرد. آخرین خطا: {0}",
"Bagher is running but not connected to the other server": "باقر اجرا می‌شود ولی به سرور مقابل وصل نیست",
"The peer's tunnel address {0} does not answer ping, but the tunnel carries data": "آدرس داخل تونل سرور مقابل ({0}) به پینگ جواب نمی‌دهد، ولی تونل داده را منتقل می‌کند",
"ICMP is filtered somewhere on the path. Nothing to do unless traffic stalls": "جایی در مسیر ICMP فیلتر شده است. تا وقتی ترافیک قطع نشده، کاری لازم نیست",
"The GRE tunnel on the other server is down, or one side has the wrong public IP. Check the Tunnel tab on the other server": "تونل GRE روی سرور مقابل خاموش است، یا IP عمومی یکی از دو طرف اشتباه است. تب تونل را روی سرور مقابل بررسی کنید",
"The peer's public IP {1} does not answer either: the other server may be down or the route is filtered": "IP عمومی سرور مقابل ({1}) هم جواب نمی‌دهد. ممکن است آن سرور خاموش باشد یا مسیر فیلتر شده باشد",
"The peer's tunnel address {0} does not answer (100% loss)": "آدرس داخل تونل سرور مقابل ({0}) جواب نمی‌دهد (۱۰۰٪ از دست رفتن بسته)",
"High packet loss through the tunnel: {0}%": "از دست رفتن بسته در تونل زیاد است: {0}٪",
"Loss this high comes from the route. Try another carrier (Benchmark tab)": "این مقدار از دست رفتن بسته از مسیر است. حامل دیگری را امتحان کنید (تب بنچمارک)",
"Some packet loss through the tunnel: {0}%": "مقداری از بسته‌ها در تونل از دست می‌رود: {0}٪",
"Watch it. If it grows, try another carrier (Benchmark tab)": "زیر نظرش داشته باشید. اگر بیشتر شد، حامل دیگری را امتحان کنید (تب بنچمارک)",
"High jitter: {0} ms": "جیتر زیاد است: {0} میلی‌ثانیه",
"The route is unstable. Calls and games will stutter": "مسیر ناپایدار است. تماس‌ها و بازی‌ها قطع‌ووصل می‌شوند",
"High latency through the tunnel: {0} ms": "تأخیر تونل زیاد است: {0} میلی‌ثانیه",
"Expected on long routes. A closer foreign server or another carrier lowers it": "در مسیرهای طولانی طبیعی است. سرور خارج نزدیک‌تر یا حامل دیگر آن را کم می‌کند",
"The peer's public IP does not answer ping (ICMP filtered); the tunnel itself works": "IP عمومی سرور مقابل به پینگ جواب نمی‌دهد (ICMP فیلتر است)، ولی خود تونل کار می‌کند",
"Packets of {0} bytes do not cross the tunnel; the largest that does is {1}": "بسته‌های {0} بایتی از تونل رد نمی‌شوند. بزرگ‌ترین بسته‌ای که رد می‌شود {1} بایت است",
"Quick Repair sets the GRE MTU to {2} and TCP MSS to {3} and keeps them after restarts. Run Diagnostics on the other server too. Until then, large downloads and TLS handshakes can stall": "Quick Repair مقدار MTU تونل GRE را {2} و MSS را {3} می‌گذارد و بعد از ری‌استارت هم نگهشان می‌دارد. روی سرور دیگر هم Diagnostics را اجرا کنید. تا آن موقع دانلودهای بزرگ و دست‌دادن TLS ممکن است گیر کنند",
"MTU not measured: large pings got no reply": "MTU سنجیده نشد، چون پینگ‌های بزرگ جوابی نگرفتند",
"TCP BBR is off (running {0})": "TCP BBR خاموش است (الگوریتم فعلی: {0})",
"BBR keeps throughput up on lossy routes. Quick Repair enables it": "BBR سرعت را در مسیرهای پرافت بالا نگه می‌دارد. تعمیر سریع روشنش می‌کند",
"IP forwarding is off": "فوروارد IP خاموش است",
"GRE cannot route traffic without it. Quick Repair enables it": "بدون آن GRE نمی‌تواند ترافیک را مسیریابی کند. تعمیر سریع روشنش می‌کند",
"No TCP MSS clamp rule": "قانون MSS clamp وجود ندارد",
"Without it, TLS handshakes through GRE can freeze. Quick Repair adds MSS 1340": "بدون آن دست‌دادن TLS از طریق GRE ممکن است گیر کند. تعمیر سریع MSS 1340 را اضافه می‌کند",
"Listen backlog (somaxconn) is low: {0}": "صف اتصال‌های ورودی (somaxconn) کم است: {0}",
"Connections drop under load. Quick Repair raises it to 65535": "زیر بار، اتصال‌ها رد می‌شوند. تعمیر سریع آن را به 65535 می‌رساند",
"Engine open-files limit is low: {0}": "سقف فایل‌های باز موتور کم است: {0}",
"The engine runs out of sockets under heavy use. Quick Repair raises it to 1048576": "موتور زیر بار سنگین سوکت کم می‌آورد. تعمیر سریع آن را به 1048576 می‌رساند",
"Needs a GRE tunnel: iPerf3 measures the GRE link": "به تونل GRE نیاز دارد، چون iPerf3 لینک GRE را می‌سنجد",
"Skipped: the peer does not answer through the tunnel": "انجام نشد، چون سرور مقابل از داخل تونل جواب نمی‌دهد",
"iperf3 is not installed here. Start iPerf3 Server installs it": "iperf3 روی این سرور نصب نیست. «شروع سرور iPerf3» آن را نصب می‌کند",
"No iPerf3 server on the other server. Press Start iPerf3 Server there, then run diagnostics here": "سرور مقابل iPerf3 ندارد. آنجا «شروع سرور iPerf3» را بزنید و بعد اینجا عیب‌یابی را اجرا کنید",
"Measured with iPerf3 for 3 seconds": "با iPerf3 در ۳ ثانیه سنجیده شد",
"Run Diagnostics checks the tunnel end to end: every tunnel's service, session and data path, ping inside and outside the tunnel, MTU, throughput and kernel settings.": "«اجرای عیب‌یابی» تونل را از اول تا آخر بررسی می‌کند: سرویس، نشست و مسیر داده‌ی هر تونل، پینگ داخل و بیرون تونل، MTU، سرعت و تنظیمات کرنل.",
"Copy Report": "کپی گزارش",
"No report yet. Press Run Diagnostics.": "هنوز گزارشی نیست. «اجرای عیب‌یابی» را بزنید.",
"Tunnels": "تونل‌ها",
"Service · Session · Data": "سرویس · نشست · داده",
"Both directions, then fix": "هر دو جهت، بعد رفع مشکل",
"Ping through the GRE tunnel": "پینگ از داخل تونل GRE",
