"Min / Max": "کمترین / بیشترین",
"Peer public IP": "IP عمومی سرور مقابل",
"Largest packet that crosses the tunnel unfragmented": "بزرگ‌ترین بسته‌ای که بدون تکه‌تکه شدن از تونل رد می‌شود",
"Interface MTU": "MTU اینترفیس",
"Recommended TCP MSS": "MSS پیشنهادی",
"MSS clamp rule": "قانون MSS clamp",
"Throughput": "سرعت انتقال",
