"IP forwarding": "فوروارد IP",
"Listen backlog": "صف اتصال‌های ورودی",
"Engine open-files limit": "سقف فایل‌های باز موتور",
"Everything checks out. The tunnel is healthy.": "همه‌چیز درست است. تونل سالم است.",
"1 critical problem: the tunnel is not working properly. Fix it first.": "۱ مشکل جدی: تونل درست کار نمی‌کند. اول این را رفع کنید.",
"{0} critical problems: the tunnel is not working properly. Fix them first.": "{0} مشکل جدی: تونل درست کار نمی‌کند. اول این‌ها را رفع کنید.",
"The tunnel works. 1 thing can be improved.": "تونل کار می‌کند. ۱ مورد را می‌شود بهتر کرد.",
"The tunnel works. {0} things can be improved.": "تونل کار می‌کند. {0} مورد را می‌شود بهتر کرد.",
"Checked": "بررسی",
"1 finding": "۱ مورد",
