"Measured on GRE tunnels only": "فقط روی تونل GRE سنجیده می‌شود",
"Measured when the peer answers through the tunnel": "وقتی سرور مقابل از داخل تونل جواب دهد سنجیده می‌شود",
"Missing": "وجود ندارد",
"Not needed": "لازم نیست",
"Unknown": "نامشخص",
