"Speed settings for the tunnel engine and the server's network stack. The defaults suit traffic that is already encrypted, such as VLESS, Reality and Trojan.": "تنظیمات سرعت برای موتور تونل و شبکه‌ی سرور. پیش‌فرض‌ها برای ترافیکی مناسب‌اند که از قبل رمزنگاری شده، مثل VLESS، Reality و Trojan.",
