"Remove this foreign server from the pool? It is not added back by itself, even though its ports include the pool port.": "این سرور خارج از استخر حذف شود؟ حتی اگر پورت استخر را داشته باشد، خودبه‌خود دوباره اضافه نمی‌شود.",
"No new connections; open ones finish. Resume it after the maintenance.": "اتصال جدید نمی‌گیرد و اتصال‌های باز تمام می‌شوند. بعد از تعمیر «ادامه» را بزنید.",
"Cannot change the member": "تغییر عضو ممکن نشد",
"No tunnels on this server yet: add the foreign servers in Setup first.": "هنوز تونلی روی این سرور نیست: اول سرورهای خارج را در راه‌اندازی اضافه کنید.",
"Enter a port from 1 to 65535": "پورتی بین 1 تا 65535 وارد کنید",
