"In a pool": "در استخر",
"No tunnels on this server yet. Pools are made of the tunnels to your foreign servers (Setup).": "هنوز تونلی روی این سرور نیست. استخرها از تونل‌های سرورهای خارج شما ساخته می‌شوند (راه‌اندازی).",
"No other Iran hub is linked. Show Join Code here and paste it on the other Iran server.": "هیچ هاب ایرانِ دیگری وصل نیست. «نمایش کد اتصال» را بزنید و کد را روی سرور ایرانِ دیگر بچسبانید.",
