"the foreign server stopped answering ping on the tunnel path": "سرور خارج روی مسیر تونل دیگر به پینگ جواب نمی‌دهد",
"Cluster — Hashem Pro": "کلاستر — Hashem Pro",
"The cluster is a Hashem Pro feature: pools of foreign servers behind one port, linked Iran hubs and DNS failover. Pools that already run keep running without it.": "کلاستر یک قابلیت Hashem Pro است: استخر سرورهای خارج پشت یک پورت، هاب‌های ایرانِ متصل و جابه‌جایی DNS. استخرهایی که از قبل کار می‌کنند بدون لایسنس هم ادامه می‌دهند.",
"New connections go to the servers with the fewest open connections (per unit of weight). Best for long connections such as VLESS and VMess.": "اتصال‌های جدید به سرورهایی می‌روند که کمترین اتصال باز را دارند (به نسبت وزن). برای اتصال‌های طولانی مثل VLESS و VMess بهترین است.",
"Least connections": "کمترین اتصال",
