"Service check every": "بررسی سرویس هر",
"Failback is manual.": "برگشت دستی است.",
"Failing back": "در حال برگشت",
"New connections go to the first server again; open ones stay where they are.": "اتصال‌های جدید دوباره به سرور اول می‌روند؛ اتصال‌های باز همان‌جا می‌مانند.",
