"Enter a port, a list (443, 8443) or a range (2000-2005), at most 50 ports": "یک پورت، یک فهرست (443, 8443) یا یک بازه (2000-2005) وارد کنید؛ حداکثر ۵۰ پورت",
"Pools saved": "استخرها ذخیره شدند",
