"the connection was closed at once: the service on the foreign server did not take it": "اتصال بلافاصله بسته شد: سرویسِ روی سرور خارج آن را نپذیرفت",
"the connection was reset: the service on the foreign server did not take it": "اتصال ریست شد: سرویسِ روی سرور خارج آن را نپذیرفت",
"Several at once: 443, 8443 or 2000-2005 (one pool each).": "چند پورت با هم: 443, 8443 یا 2000-2005 (برای هر کدام یک استخر).",
"Failback": "برگشت به سرور اول",
