"TCP: connect through the tunnel": "TCP: اتصال از داخل تونل",
"Check every (seconds)": "بررسی هر (ثانیه)",
"The service check opens a connection through each foreign server to the service behind it (for example xray on 443). A server whose tunnel is up but whose service refuses the connection is taken out. TCP pools only.": "بررسی سرویس از طریق هر سرور خارج به سرویسِ پشت آن (مثلاً xray روی 443) وصل می‌شود. سروری که تونلش وصل است اما سرویسش اتصال را نمی‌پذیرد کنار گذاشته می‌شود. فقط برای استخرهای TCP.",
"Provider": "سرویس‌دهنده",
"Webhook (any DNS provider or script)": "وب‌هوک (هر سرویس‌دهنده‌ی DNS یا اسکریپت)",
"Webhook URL": "آدرس وب‌هوک",
"The hub that leads POSTs JSON {\"name\", \"ips\", \"ips6\", \"ttl\", \"hub\", \"at\"} whenever the working hubs change, and every 30 seconds. Your script sets the record to exactly \"ips\" (A) and \"ips6\" (AAAA). Any 2xx answer counts as done.": "هابِ هماهنگ‌کننده هر بار که فهرست هاب‌های سالم عوض شود، و هر ۳۰ ثانیه، یک JSON به شکل {\"name\", \"ips\", \"ips6\", \"ttl\", \"hub\", \"at\"} با POST می‌فرستد. اسکریپت شما رکورد را دقیقاً برابر \"ips\" (A) و \"ips6\" (AAAA) می‌گذارد. هر پاسخ 2xx یعنی انجام شد.",
"A domain that always points to the Iran hubs that work.": "دامنه‌ای که همیشه به هاب‌های ایرانِ سالم اشاره می‌کند.",
"Add to a pool": "افزودن به استخر",
"Add to a pool…": "افزودن به استخر…",
"Back to Pool": "بازگشت به استخر",
"Carries traffic": "ترافیک دارد",
"Click a server to change its settings in this pool.": "برای تغییر تنظیمات یک سرور در این استخر، روی آن کلیک کنید.",
"Click any part of the map to see and change it. Line thickness is the share of new connections; color is health.": "روی هر بخش از نقشه کلیک کنید تا آن را ببینید و تغییر دهید. ضخامت خط سهم اتصال‌های جدید و رنگ آن سلامت است.",
"Cluster Map": "نقشه‌ی کلاستر",
