"Open Tunnel Tab": "باز کردن تب تونل",
"Pool": "استخر",
"Serves several Iran hubs: when one Iran server dies, users who connect through the others keep working.": "چند هاب ایران را سرویس می‌دهد: وقتی یک سرور ایران از کار بیفتد، کاربرانی که از بقیه وصل‌اند کارشان ادامه دارد.",
"Service check: connect through the tunnel to the service": "بررسی سرویس: اتصال از داخل تونل به سرویس",
"Settings of this server in pool": "تنظیمات این سرور در استخر",
"Standby, DNS or linked hub": "آماده، DNS یا هاب متصل",
"Standby: traffic only when no other server can take it": "آماده: فقط وقتی ترافیک می‌گیرد که سرور دیگری نتواند",
"Sticky": "ثابت",
"The first hub is set up in Setup.": "هاب اول در راه‌اندازی تنظیم می‌شود.",
"The tunnel itself (ports, transport, token) is edited in the Tunnel tab.": "خودِ تونل (پورت‌ها، ترنسپورت، توکن) در تب تونل ویرایش می‌شود.",
"This Iran hub": "این هاب ایران",
"This foreign server": "این سرور خارج",
"Users connect to this hub's public IP, or to the DNS name when DNS failover is on. Each pool sends their new connections to a working foreign server.": "کاربرها به IP عمومی این هاب وصل می‌شوند، یا اگر جابه‌جایی DNS روشن باشد به نام دامنه. هر استخر اتصال‌های جدیدشان را به یک سرور خارجِ سالم می‌فرستد.",
"Weight counts in balance, sticky and least connections; priority in failover (lower first).": "وزن در Balance، Sticky و کمترین اتصال اثر دارد؛ اولویت در Failover (عدد کمتر اول).",
"When every foreign server of a pool is down here, its port is forwarded to a hub where the same pool works.": "وقتی همه‌ی سرورهای خارجِ یک استخر اینجا قطع باشند، پورت آن به هابی فرستاده می‌شود که همان استخر در آن سالم است.",
