"Key file (server end)": "فایل کلید (سمت سرور)",
"TTI (ms)": "TTI (میلی‌ثانیه)",
"Upload capacity (MB/s)": "ظرفیت آپلود (MB/s)",
"Download capacity (MB/s)": "ظرفیت دانلود (MB/s)",
"Mux concurrency (0 = off)": "همزمانی Mux (0 = خاموش)",
"TCP congestion": "کنترل ازدحام TCP",
