"Packets": "پکت‌ها",
"Length": "طول",
"Delay (ms)": "تأخیر (میلی‌ثانیه)",
"The Iran server connects to the foreign server. The usual choice.": "سرور ایران به سرور خارج وصل می‌شود. انتخاب معمول.",
"The foreign server connects to the Iran server. Use it when the Iran server cannot reach the foreign one, or its connections out get cut.": "سرور خارج به سرور ایران وصل می‌شود. وقتی سرور ایران به خارج نمی‌رسد یا اتصال‌های خروجی‌اش قطع می‌شود، این را انتخاب کن.",
