"through Cloudflare as": "از طریق Cloudflare با نام",
"this server's IP": "IP این سرور",
"the foreign server's IP": "IP سرور خارج",
"A domain or subdomain whose DNS is on Cloudflare.": "دامنه یا ساب‌دامنه‌ای که DNS آن روی Cloudflare است.",
"The address the dialing server connects to. Empty: the domain itself.": "آدرسی که سرور وصل‌شونده به آن وصل می‌شود. خالی یعنی خود دامنه.",
"On Cloudflare": "در Cloudflare",
"DNS: an A record for the domain to": "DNS: یک رکورد A برای دامنه به",
"with the proxy on (orange cloud).": "با پروکسی روشن (ابر نارنجی).",
"SSL/TLS mode: Full (not Full strict). The link uses a certificate the panel makes for the domain.": "حالت SSL/TLS: Full (نه Full strict). لینک از گواهی‌ای استفاده می‌کند که پنل برای دامنه می‌سازد.",
"Network: turn on WebSockets or gRPC if you pick those transports in the advanced settings.": "Network: اگر در تنظیمات پیشرفته WebSocket یا gRPC را انتخاب کردی، آن را روشن کن.",
"Cloudflare passes HTTPS only on these ports.": "Cloudflare فقط روی این پورت‌ها HTTPS را عبور می‌دهد.",
"Through a CDN (Cloudflare)": "از طریق CDN (Cloudflare)",
"Enter the domain on Cloudflare.": "دامنه‌ی روی Cloudflare را وارد کن.",
"Enter the TLS server name.": "نام سرور TLS را وارد کن.",
"It goes in the domain's DNS record; the Iran server connects through Cloudflare.": "در رکورد DNS دامنه قرار می‌گیرد؛ سرور ایران از طریق Cloudflare وصل می‌شود.",
"Through Cloudflare: a censor sees only a Cloudflare site, and a blocked server IP stays reachable. Needs a domain on Cloudflare.": "از طریق Cloudflare: فیلترینگ فقط یک سایت Cloudflare می‌بیند و IP مسدودشده‌ی سرور هم در دسترس می‌ماند. یک دامنه روی Cloudflare لازم دارد.",
